-- Applied to the dedicated HOROOF Supabase project. The schema is private;
-- no anonymous/authenticated policies are granted. API implementation pending.
CREATE SCHEMA IF NOT EXISTS horoof;
REVOKE ALL ON SCHEMA horoof FROM PUBLIC, anon, authenticated;
CREATE TABLE horoof.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE CHECK (char_length(username) BETWEEN 3 AND 40), interface_locale text NOT NULL DEFAULT 'en' CHECK (interface_locale IN ('ar','fr','en')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.subjects (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, owner_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 120), description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.questions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, subject_id bigint NOT NULL REFERENCES horoof.subjects(id) ON DELETE CASCADE, letter text NOT NULL, question text NOT NULL, answer text NOT NULL, language text NOT NULL DEFAULT 'ar' CHECK(language IN ('ar','fr','en')), review_status text NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.rooms (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, host_id uuid NOT NULL REFERENCES auth.users(id), subject_id bigint NOT NULL REFERENCES horoof.subjects(id), status text NOT NULL DEFAULT 'lobby' CHECK(status IN ('lobby','playing','finished','closed')), max_players integer NOT NULL DEFAULT 8 CHECK(max_players BETWEEN 2 AND 32), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.room_players (room_id bigint NOT NULL REFERENCES horoof.rooms(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, team text NOT NULL CHECK(team IN ('green','orange')), ready boolean NOT NULL DEFAULT false, score integer NOT NULL DEFAULT 0 CHECK(score>=0), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,user_id));
CREATE TABLE horoof.games (room_id bigint PRIMARY KEY REFERENCES horoof.rooms(id) ON DELETE CASCADE, board jsonb NOT NULL CHECK(jsonb_typeof(board)='array' AND jsonb_array_length(board)=25), active_cell integer CHECK(active_cell BETWEEN 0 AND 24), question_id bigint REFERENCES horoof.questions(id), winner_user uuid REFERENCES auth.users(id), answer_deadline timestamptz, turn_team text CHECK(turn_team IN ('green','orange')), result text CHECK(result IN ('green','orange')), round_version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.buzzes (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, room_id bigint NOT NULL REFERENCES horoof.rooms(id) ON DELETE CASCADE, round_version integer NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id), received_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(room_id,round_version,user_id));
CREATE TABLE horoof.answers (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, room_id bigint NOT NULL REFERENCES horoof.rooms(id) ON DELETE CASCADE, question_id bigint NOT NULL REFERENCES horoof.questions(id), user_id uuid NOT NULL REFERENCES auth.users(id), raw_answer text NOT NULL, correct boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.documents (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, subject_id bigint NOT NULL REFERENCES horoof.subjects(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, filename text NOT NULL, storage_key text NOT NULL, mime text NOT NULL, size bigint NOT NULL, checksum text NOT NULL, status text NOT NULL DEFAULT 'uploaded', error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE horoof.document_chunks (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, document_id bigint NOT NULL REFERENCES horoof.documents(id) ON DELETE CASCADE, page integer, chunk_order integer NOT NULL, text text NOT NULL, UNIQUE(document_id,chunk_order));
CREATE INDEX ON horoof.questions(subject_id,letter,review_status);
CREATE INDEX ON horoof.room_players(user_id);
CREATE INDEX ON horoof.buzzes(room_id,round_version,id);
CREATE INDEX ON horoof.answers(user_id,created_at);
CREATE INDEX ON horoof.documents(owner_id,subject_id);
ALTER TABLE horoof.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.rooms ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.room_players ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.games ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.buzzes ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE horoof.document_chunks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA horoof FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA horoof FROM PUBLIC, anon, authenticated;
